#pragma once

#include "aegisproxy/common/result.hpp"

#include <cstdint>
#include <string_view>

namespace aegis::net {

/// Lifecycle of a client connection as seen by the proxy.
///
///   Accepted → ReadingRequest → SelectingBackend → ConnectingBackend
///            → ForwardingRequest → AwaitingResponse → WritingResponse
///            → (keep-alive) ReadingRequest | Closing → Closed
///
/// Any non-terminal state may go to Closing (errors, timeouts, peer hang-up).
/// Error responses generated by the proxy itself (e.g. 502) jump straight to
/// WritingResponse from SelectingBackend / ConnectingBackend / AwaitingResponse.
enum class ConnectionState : std::uint8_t {
  Accepted = 0,
  ReadingRequest,
  SelectingBackend,
  ConnectingBackend,
  ForwardingRequest,
  AwaitingResponse,
  WritingResponse,
  Closing,
  Closed,
};

[[nodiscard]] std::string_view to_string(ConnectionState state) noexcept;

/// Validates transitions so that protocol bugs surface as InvalidState errors instead
/// of silent corruption. Owned by Connection; driven by HttpProxy (Member 2).
class ConnectionStateMachine {
 public:
  ConnectionStateMachine() = default;
  /// Backend-role connections start in ConnectingBackend (see Connection::role()).
  explicit ConnectionStateMachine(ConnectionState initial) noexcept : state_(initial) {}

  [[nodiscard]] ConnectionState state() const noexcept { return state_; }
  [[nodiscard]] bool is_terminal() const noexcept { return state_ == ConnectionState::Closed; }

  /// True iff the transition is allowed by the table above.
  [[nodiscard]] static bool is_valid_transition(ConnectionState from, ConnectionState to) noexcept;

  /// Applies the transition or returns InvalidState (state unchanged).
  Status transition_to(ConnectionState next);

 private:
  ConnectionState state_{ConnectionState::Accepted};
};

}  // namespace aegis::net
